import{_ as d,C as o,o as r,c as n,E as a,a4 as c}from"./chunks/framework.BMj-uaUw.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"先看一个真实的报修单","slug":"先看一个真实的报修单","link":"#先看一个真实的报修单","children":[]},{"level":2,"title":"为什么表单值得单独讲一个单元","slug":"为什么表单值得单独讲一个单元","link":"#为什么表单值得单独讲一个单元","children":[]},{"level":2,"title":"本单元的知识地图","slug":"本单元的知识地图","link":"#本单元的知识地图","children":[]},{"level":2,"title":"这次课的 4 学时怎么用","slug":"这次课的-4-学时怎么用","link":"#这次课的-4-学时怎么用","children":[]},{"level":2,"title":"开始之前","slug":"开始之前","link":"#开始之前","children":[]},{"level":2,"title":"这个单元的两个产出","slug":"这个单元的两个产出","link":"#这个单元的两个产出","children":[]},{"level":2,"title":"读完之后","slug":"读完之后","link":"#读完之后","children":[]}],"relativePath":"unit06/index.md","filePath":"unit06/index.md","lastUpdated":1789356894000}'),l={name:"unit06/index.md"};function i(s,t,h,g,u,p){const e=o("UnitMeta");return r(),n("div",null,[a(e,{unit:"单元 6",title:"用户交互与表单绑定",module:"模块二 · Vue 3 核心基础",hours:"4 学时",week:"第 6 周",goals:["能处理各类用户交互，并正确选用事件修饰符","能完成一个带完整校验的表单页面","能在正确的时机做数据初始化，并在组件卸载时清理副作用"],outcomes:["多步预订表单","Markdown 编辑器"]}),t[0]||(t[0]=c('<h2 id="先看一个真实的报修单" tabindex="-1">先看一个真实的报修单 <a class="header-anchor" href="#先看一个真实的报修单" aria-label="Permalink to &quot;先看一个真实的报修单&quot;">​</a></h2><p>学期初，活动运营的同学提了一个问题：</p><blockquote><p>“我们那个活动报名页面，学生点两次提交就报了两条报名记录；备注框里打完字，切换输入法之后第一段字没了；手机号那一栏我填了 13800000000，提交上去变成了数字，后台校验又说格式不对。”</p></blockquote><p>这三个问题，一个属于<strong>重复提交</strong>，一个属于<strong>输入法组合期的事件处理</strong>，一个属于<strong>表单取值的类型</strong>。 它们看起来互不相关，其实指向同一个能力：<strong>你知不知道用户的一次操作，在浏览器里到底发生了什么，Vue 又替你做了什么。</strong></p><p>这个单元就解决这件事。</p><h2 id="为什么表单值得单独讲一个单元" tabindex="-1">为什么表单值得单独讲一个单元 <a class="header-anchor" href="#为什么表单值得单独讲一个单元" aria-label="Permalink to &quot;为什么表单值得单独讲一个单元&quot;">​</a></h2><p>前面四个单元，数据都是你写的：你在 <code>setup</code> 里定义一个数组，页面就渲染出列表。 从这一单元开始，<strong>数据由用户产生</strong>。用户产生数据的方式比你想的多：</p><table tabindex="0"><thead><tr><th>用户动作</th><th>触发的事件</th><th>数据在哪</th></tr></thead><tbody><tr><td>在文本框打字</td><td><code>input</code>、<code>change</code></td><td><code>event.target.value</code></td></tr><tr><td>勾选复选框</td><td><code>change</code></td><td><code>event.target.checked</code>，多选还要分组</td></tr><tr><td>从下拉框选一项</td><td><code>change</code></td><td><code>event.target.value</code></td></tr><tr><td>按回车提交</td><td><code>keydown</code>、<code>submit</code></td><td>关键在于阻止默认行为</td></tr><tr><td>把表格内容粘进来</td><td><code>paste</code></td><td>剪贴板文本，还可能是多行</td></tr><tr><td>滚动到页面底部</td><td><code>scroll</code></td><td>需要节流，还要清理监听</td></tr><tr><td>窗口尺寸变化</td><td><code>resize</code></td><td>组件卸载时忘了取消就会出问题</td></tr></tbody></table><p>而这批数据一旦“乱”起来，代价比列表渲染大得多：<strong>列表渲染错了，页面显示不对；表单数据错了，会写进数据库。</strong></p><p>所以这个单元的定位是：<strong>把用户输入变成可靠的数据。</strong></p><h2 id="本单元的知识地图" tabindex="-1">本单元的知识地图 <a class="header-anchor" href="#本单元的知识地图" aria-label="Permalink to &quot;本单元的知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小节</th><th>讲什么</th><th>解决什么问题</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/unit06/01-events.html">6.1 事件处理的完整写法</a></td><td>内联表达式与方法引用、<code>$event</code> 的取法、常见事件类型与触发时机</td><td>为什么我拿不到事件对象</td></tr><tr><td><a href="/frontend-engineering-course/unit06/02-modifiers.html">6.2 事件与按键修饰符</a></td><td><code>.stop</code> <code>.prevent</code> <code>.self</code> <code>.once</code> <code>.passive</code>、按键与系统修饰键</td><td>为什么点按钮把弹窗也关了</td></tr><tr><td><a href="/frontend-engineering-course/unit06/03-form-binding.html">6.3 表单绑定</a></td><td><code>v-model</code> 在七种表单元素上的形态与取值类型、三个表单修饰符</td><td>为什么复选框选一个就全变</td></tr><tr><td><a href="/frontend-engineering-course/unit06/04-validation.html">6.4 表单校验</a></td><td>即时校验与提交校验、规则函数、异步校验、重复提交防护</td><td>校验逻辑越写越乱怎么办</td></tr><tr><td><a href="/frontend-engineering-course/unit06/05-lifecycle.html">6.5 生命周期与副作用清理</a></td><td><code>onMounted</code> 等钩子、模板引用、定时器与监听的清理时机</td><td>切换页面后报错从哪来</td></tr><tr><td><a href="/frontend-engineering-course/unit06/06-case-markdown.html">案例 05 · Markdown 编辑器</a></td><td>实时预览、工具栏插入、滚动同步、草稿自动保存</td><td>综合练手</td></tr><tr><td><a href="/frontend-engineering-course/unit06/ai-collaboration.html">AI 协作 · 表单校验与副作用清理</a></td><td>事件名大小写、<code>v-model</code> 修饰符语义、卸载时清副作用</td><td>表单是 bug 最集中的地方</td></tr><tr><td><a href="/frontend-engineering-course/unit06/practice.html">课后练习</a></td><td>报名表单、回车提交、副作用清理、多步表单</td><td>上手做</td></tr></tbody></table><p>六节之间是递进关系：先学会<strong>接住用户的操作</strong>（6.1、6.2），再把操作变成<strong>受控的数据</strong>（6.3）， 然后保证数据<strong>可信</strong>（6.4），最后解决“<strong>这些操作什么时候该结束</strong>”（6.5）。</p><h2 id="这次课的-4-学时怎么用" tabindex="-1">这次课的 4 学时怎么用 <a class="header-anchor" href="#这次课的-4-学时怎么用" aria-label="Permalink to &quot;这次课的 4 学时怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>检查预习</td><td>0.3 学时</td><td>抽问：<code>input</code> 和 <code>change</code> 有什么区别？为什么提交表单要 <code>preventDefault</code>？</td></tr><tr><td>讲解</td><td>1.4 学时</td><td>重点讲 6.1 的事件对象与 6.3 的取值类型表；6.2 与 6.4 讲清“拦掉的是什么”和“校验顺序”</td></tr><tr><td>现场任务</td><td>1.8 学时</td><td>两人一组做“活动报名表单”，至少覆盖三种元素类型与两类校验规则</td></tr><tr><td>复盘</td><td>0.5 学时</td><td>挑两组演示，重点看错误提示的位置与重复提交有没有防住</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这次课最容易含糊过去的三个点</p><ol><li><strong><code>input</code> 与 <code>change</code></strong> —— 很多人以为是一回事，写校验时用了 <code>change</code>，结果用户边打字边看不到提示。</li><li><strong>多个复选框的 <code>v-model</code></strong> —— 不在 <code>v-model</code> 上写数组初值，点一个选项其他的也跟着变，还看不懂原因。</li><li><strong>副作用清理</strong> —— 定时器、<code>resize</code> 监听、没取消的请求。开发时看不出来，一上线就是“内存一路涨”。</li></ol></div><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><p>这一单元要求你先掌握前两个单元的内容，具体是：</p><ul><li><strong>单元 4</strong>：<code>ref</code> 怎么声明、模板里怎么取值、<code>@click</code> 是什么。这些是事件处理的地基。</li><li><strong>单元 5</strong>：<code>computed</code> 与 <code>watch</code>、<code>v-if</code> 与 <code>v-for</code>、<code>v-for</code> 的 <code>:key</code> 怎么写。校验与列表渲染会用到。</li></ul><p>如果这两块还没做熟，建议先回去把 <a href="/frontend-engineering-course/unit04/04-reactivity.html">4.4 <code>ref</code> 与 <code>reactive</code></a> 和 <a href="/frontend-engineering-course/unit05/01-computed.html">5.1 计算属性与缓存</a> 的练习做完。</p><p>另外准备两样东西：</p><ol><li><strong>Chrome 或 Edge 浏览器</strong>，会用 DevTools 的 Elements 面板看元素属性 —— 讲 <code>v-model</code> 本质时会用到。</li><li><strong>一个能跑起来的 Vue 3 项目</strong>。还没建的话，按 <a href="/frontend-engineering-course/unit02/04-vite.html">2.4 构建工具与 Vite</a> 用 <code>create-vue</code> 建一个。</li></ol><h2 id="这个单元的两个产出" tabindex="-1">这个单元的两个产出 <a class="header-anchor" href="#这个单元的两个产出" aria-label="Permalink to &quot;这个单元的两个产出&quot;">​</a></h2><p>课程要求这次课交两样东西，考核时都会看。</p><p><strong>一、多步预订表单</strong></p><p>不是“能填就行”的表单，而是一个<strong>分两步</strong>的场地预订表单：第一步填活动与时段，第二步填联系人与备注。 要求：</p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>分步</td><td>每一步独立校验，第一步不通过不能进第二步</td></tr><tr><td>可回退</td><td>能返回上一步，<strong>已经填过的数据不能丢</strong></td></tr><tr><td>提交</td><td>提交中按钮禁用，重复点击不会产生两条记录</td></tr><tr><td>错误提示</td><td>错误显示在对应字段下方，不是弹一个“输入有误”</td></tr></tbody></table><p><strong>二、Markdown 编辑器</strong></p><p>左侧输入、右侧实时预览的编辑器。要求：</p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>语法</td><td>至少支持标题、粗体、斜体、列表、链接、代码块</td></tr><tr><td>工具栏</td><td>点按钮能在光标处插入语法，<strong>光标位置要回到插入内容之后</strong></td></tr><tr><td>安全</td><td>预览用 <code>v-html</code> 渲染，渲染前必须先把用户输入转义</td></tr><tr><td>草稿</td><td>刷新页面后草稿还在</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">这两个产出其实是同一件事</p><p>多步表单练的是<strong>把输入变成可信数据</strong>，Markdown 编辑器练的是<strong>把输入变成安全内容</strong>。 两条线都绕不开“用户是可以随便输入的”这个前提。</p></div><h2 id="读完之后" tabindex="-1">读完之后 <a class="header-anchor" href="#读完之后" aria-label="Permalink to &quot;读完之后&quot;">​</a></h2><p>这个单元结束时，你应该能对着一个表单说出三句话：</p><ol><li>这个输入框的 <code>v-model</code> 绑的是<strong>什么类型</strong>的值。</li><li>校验在<strong>什么时候</strong>跑，错误提示<strong>显示在哪</strong>。</li><li>这个组件<strong>创建了什么副作用</strong>，在<strong>哪里</strong>清理掉。</li></ol><p>下一单元进入<a href="/frontend-engineering-course/unit07/">单元 7：组件基础与父子通信</a>。到那时你会把这一单元的表单拆成组件， 让子组件负责输入、父组件负责数据 —— 而这三个问题的答案，正是拆分时最先要交代清楚的东西。</p>',35))])}const f=d(l,[["render",i]]);export{b as __pageData,f as default};
